func (s *Store) CurrentVersion(org string) (int, error) {
	if org == "" {
		return 0, fmt.Errorf("%w: organization is required", ErrInvalidOrganization)
	}
	o := s.org(org)
	o.mu.Lock()
	defer o.mu.Unlock()
	return o.current, nil
}
```

