	_, _ = s.Publish(testOrg, 0, []Policy{allowPolicy("p1", "u1", "read", "a", false)})
	// decision reads version once; concurrent publish must not mix policies
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for i := 0; i < 100; i++ {
			d := s.Decide(testOrg, testSubject("u1"), testResource("r1", "a"), "read")
			if d.Version != 1 && d.Version != 2 {
				t.Errorf("decision version = %d, want 1 or 2", d.Version)
			}
		}
	}()
	go func() {
		defer wg.Done()
		for i := 0; i < 100; i++ {
			_, _ = s.Publish(testOrg, s.CurrentVersionOrZero(), []Policy{denyPolicy("p2", "u1", "read", "a")})
		}
	}()
	wg.Wait()
}

