1	package darksafe
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7		"strings"
8		"sync"
9	)
10	
11	// Effect is the decision a policy produces when it matches.
12	type Effect string
13	
14	const (
15		// EffectAllow grants access when the policy matches.
16		EffectAllow Effect = "allow"
17		// EffectDeny refuses access when the policy matches; it takes precedence
18		// over any matching allow policy.
19		EffectDeny Effect = "deny"
20	)
21	
22	// Policy is one authorization rule published by an organization.
23	//
24	// A policy identifies a single subject, a single action and a scope path,
25	// and either allows or denies the request. When Recursive is true the policy
26	// also covers every scope below Scope; otherwise it covers only Scope itself.
27	type Policy struct {
28		ID        string
29		Subject   string
30		Action    string
31		Scope     string
32		Effect    Effect
33		Recursive bool
34	}
35	
36	// Version is an immutable, complete snapshot of an organization's published
37	// policy set at a point in time.
38	type Version struct {
39		Number   int
40		Policies []Policy
41	}
42	
43	// Distinguishable failure reasons returned in Decision.Reason.
44	const (
45		ReasonMissingOrganization       = "missing organization"
46		ReasonMissingSubjectOrg         = "missing subject organization"
47		ReasonMissingResourceOrg        = "missing resource organization"
48		ReasonSubjectOrgMismatch        = "subject organization does not match decision organization"
49		ReasonResourceOrgMismatch       = "resource organization does not match decision organization"
50		ReasonMissingSubject            = "missing subject identifier"
51		ReasonMissingResource           = "missing resource identifier"
52		ReasonMissingAction             = "missing action"
53		ReasonInvalidScope              = "invalid scope"
54		ReasonSubjectDisabled           = "subject is disabled"
55		ReasonNoPublishedVersion        = "no published version"
56		ReasonVersionNotFound           = "version not found"
57		ReasonDeniedByPolicy            = "denied by policy"
58		ReasonAllowedByPolicy           = "allowed by policy"
59		ReasonNoMatchingPolicy          = "no matching policy"
60	)
61	
62	// Sentinel errors returned by Store operations. Callers may compare with
63	// errors.Is to distinguish validation, conflict and not-found failures.
64	var (
65		// ErrInvalidOrganization is returned when the organization identifier is
66		// empty.
67		ErrInvalidOrganization = errors.New("invalid organization")
68		// ErrInvalidPolicy is returned when a published policy set fails
69		// validation.
70		ErrInvalidPolicy = errors.New("invalid policy")
71		// ErrVersionConflict is returned when a publish or rollback carries an
72		// expected version that does not match the organization's current version.
73		ErrVersionConflict = errors.New("version conflict")
74		// ErrVersionNotFound is returned when a requested historical version does
75		// not exist.
76		ErrVersionNotFound = errors.New("version not found")
77	)
78	
79	// Store holds the per-organization policy versions for the lifetime of the
80	// service instance. It is safe for concurrent use.
81	//
82	// Each organization manages its own policy set and version sequence. Different
83	// organizations may use the same subject, resource and policy identifiers
84	// without interfering with one another.
85	type Store struct {
86		mu   sync.Mutex
87		orgs map[string]*orgStore
88	}
89	
90	type orgStore struct {
91		mu       sync.RWMutex
92		current  int
93		versions map[int]*Version
94	}
95	
96	// NewStore returns an empty store. Organizations are created lazily on first
97	// publish; a new organization starts at version 0 and cannot be used for
98	// decisions until its first successful publish.
99	func NewStore() *Store {
100		return &Store{orgs: make(map[string]*orgStore)}
101	}
102	
103	func (s *Store) orgStore(org string) *orgStore {
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		o, ok := s.orgs[org]
107		if !ok {
108			o = &orgStore{versions: make(map[int]*Version)}
109			s.orgs[org] = o
110		}
111		return o
112	}
113	
114	// Publish validates policies and, only when expectedVersion matches the
115	// organization's current version, publishes the complete set as a new version.
116	// It returns the new version number.
117	//
118	// Validation failures (duplicate or empty policy identifiers, invalid scope
119	// paths, missing subject or action, unknown effect) reject the whole publish:
120	// the current version and history are left untouched and no version number is
121	// consumed. An empty policy set is valid and publishes successfully; its
122	// decisions are all denied.
123	//
124	// Publish copies policies, so later mutation of the caller's slice does not
125	// affect published history.
126	func (s *Store) Publish(org string, expectedVersion int, policies []Policy) (int, error) {
127		if org == "" {
128			return 0, fmt.Errorf("%w: organization is required", ErrInvalidOrganization)
129		}
130		if err := validatePolicies(policies); err != nil {
131			return 0, err
132		}
133		o := s.orgStore(org)
134		o.mu.Lock()
135		defer o.mu.Unlock()
136		if o.current != expectedVersion {
137			return 0, fmt.Errorf("%w: current version is %d, caller expected %d", ErrVersionConflict, o.current, expectedVersion)
138		}
139		num := o.current + 1
140		o.versions[num] = &Version{Number: num, Policies: clonePolicies(policies)}
141		o.current = num
142		return num, nil
143	}
144	
145	// Rollback publishes the complete content of targetVersion (a version already
146	// present in this organization's history) as a new version. History is never
147	// rewritten or deleted. It returns the new version number.
148	//
149	// expectedVersion must match the organization's current version for the
150	// rollback to succeed. A target that does not exist returns ErrVersionNotFound
151	// without changing the current version or history.
152	func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
153		if org == "" {
154			return 0, fmt.Errorf("%w: organization is required", ErrInvalidOrganization)
155		}
156		if targetVersion <= 0 {
157			return 0, fmt.Errorf("%w: target version %d does not exist", ErrVersionNotFound, targetVersion)
158		}
159		o := s.orgStore(org)
160		o.mu.Lock()
161		defer o.mu.Unlock()
162		if o.current != expectedVersion {
163			return 0, fmt.Errorf("%w: current version is %d, caller expected %d", ErrVersionConflict, o.current, expectedVersion)
164		}
165		target, ok := o.versions[targetVersion]
166		if !ok {
167			return 0, fmt.Errorf("%w: target version %d does not exist", ErrVersionNotFound, targetVersion)
168		}
169		num := o.current + 1
170		o.versions[num] = &Version{Number: num, Policies: clonePolicies(target.Policies)}
171		o.current = num
172		return num, nil
173	}
174	
175	// CurrentVersion returns the organization's current version. A new
176	// organization that has never published is at version 0.
177	func (s *Store) CurrentVersion(org string) (int, error) {
178		if org == "" {
179			return 0, fmt.Errorf("%w: organization is required", ErrInvalidOrganization)
180		}
181		o := s.orgStore(org)
182		o.mu.Lock()
183		defer o.mu.Unlock()
184		return o.current, nil
185	}
186	
187	// Policies returns a copy of the complete policy set of the given version in
188	// this organization's history. The returned slice is a copy: later mutation by
189	// the caller does not change published history.
190	func (s *Store) Policies(org string, version int) ([]Policy, error) {
191		if org == "" {
192			return nil, fmt.Errorf("%w: organization is required", ErrInvalidOrganization)
193		}
194		o := s.orgStore(org)
195		o.mu.Lock()
196		defer o.mu.Unlock()
197		v, ok := o.versions[version]
198		if !ok {
199			return nil, fmt.Errorf("%w: version %d does not exist", ErrVersionNotFound, version)
200		}
201		return clonePolicies(v.Policies), nil
202	}
203	
204	// Decide evaluates a request against the organization's currently published
205	// version. The request must carry the organization of the subject and of the
206	// resource, and both must match the decision organization; otherwise the
207	// request is denied even if an allow policy would match. Missing organization,
208	// subject, resource or action identifiers, and invalid scope paths, are denied
209	// with distinguishable reasons. A disabled subject is denied.
210	//
211	// The subject's own roles never grant access under a published policy set.
212	// Default deny: a matching deny policy takes precedence over any matching
213	// allow policy. The decision records the actual version used and lists every
214	// matching policy identifier, deduplicated and sorted lexicographically.
215	func (s *Store) Decide(org string, subject Subject, resource Resource, action string) Decision {
216		o := s.orgStore(org)
217		o.mu.RLock()
218		version := o.current
219		o.mu.RUnlock()
220		return s.evaluate(org, version, subject, resource, action)
221	}
222	
223	// Review re-evaluates a request against a specific historical version of the
224	// organization. Later publishes or rollbacks do not change its conclusion,
225	// reason or matched list. A version that does not exist is denied with
226	// reason VersionNotFound; the current version is never used as a fallback.
227	func (s *Store) Review(org string, version int, subject Subject, resource Resource, action string) Decision {
228		if org == "" {
229			return Decision{Allowed: false, Reason: ReasonMissingOrganization}
230		}
231		if version <= 0 {
232			return Decision{Allowed: false, Reason: fmt.Sprintf("%s: version %d", ReasonVersionNotFound, version), Version: version}
233		}
234		o := s.orgStore(org)
235		o.mu.RLock()
236		_, ok := o.versions[version]
237		o.mu.RUnlock()
238		if !ok {
239			return Decision{Allowed: false, Reason: fmt.Sprintf("%s: version %d", ReasonVersionNotFound, version), Version: version}
240		}
241		return s.evaluate(org, version, subject, resource, action)
242	}
243	
244	func (s *Store) evaluate(org string, version int, subject Subject, resource Resource, action string) Decision {
245		if org == "" {
246			return Decision{Allowed: false, Reason: ReasonMissingOrganization, Version: version}
247		}
248		if subject.Org == "" {
249			return Decision{Allowed: false, Reason: ReasonMissingSubjectOrg, Version: version}
250		}
251		if resource.Org == "" {
252			return Decision{Allowed: false, Reason: ReasonMissingResourceOrg, Version: version}
253		}
254		if subject.Org != org {
255			return Decision{Allowed: false, Reason: ReasonSubjectOrgMismatch, Version: version}
256		}
257		if resource.Org != org {
258			return Decision{Allowed: false, Reason: ReasonResourceOrgMismatch, Version: version}
259		}
260		if subject.ID == "" {
261			return Decision{Allowed: false, Reason: ReasonMissingSubject, Version: version}
262		}
263		if resource.ID == "" {
264			return Decision{Allowed: false, Reason: ReasonMissingResource, Version: version}
265		}
266		if action == "" {
267			return Decision{Allowed: false, Reason: ReasonMissingAction, Version: version}
268		}
269		if !validScopePath(resource.Scope) {
270			return Decision{Allowed: false, Reason: fmt.Sprintf("%s: %q", ReasonInvalidScope, resource.Scope), Version: version}
271		}
272		if subject.Disabled {
273			return Decision{Allowed: false, Reason: ReasonSubjectDisabled, Version: version}
274		}
275		o := s.orgStore(org)
276		o.mu.RLock()
277		v, ok := o.versions[version]
278		var policies []Policy
279		if ok {
280			policies = clonePolicies(v.Policies)
281		}
282		o.mu.RUnlock()
283		if !ok {
284			return Decision{Allowed: false, Reason: ReasonNoPublishedVersion, Version: version}
285		}
286		matched, hasAllow, hasDeny := matchPolicies(policies, subject.ID, action, resource.Scope)
287		if hasDeny {
288			return Decision{Allowed: false, Reason: ReasonDeniedByPolicy, Matched: matched, Version: version}
289		}
290		if hasAllow {
291			return Decision{Allowed: true, Reason: ReasonAllowedByPolicy, Matched: matched, Version: version}
292		}
293		return Decision{Allowed: false, Reason: ReasonNoMatchingPolicy, Matched: matched, Version: version}
294	}
295	
296	// matchPolicies returns the sorted, deduplicated identifiers of every policy
297	// matching the request, and whether any of them allows or denies it.
298	func matchPolicies(policies []Policy, subjectID, action, scope string) (matched []string, hasAllow, hasDeny bool) {
299		seen := make(map[string]bool)
300		for _, p := range policies {
301			if p.Subject != subjectID || p.Action != action {
302				continue
303			}
304			if !scopeCovers(p.Scope, scope, p.Recursive) {
305				continue
306			}
307			if !seen[p.ID] {
308				seen[p.ID] = true
309				matched = append(matched, p.ID)
310			}
311			switch p.Effect {
312			case EffectAllow:
313				hasAllow = true
314			case EffectDeny:
315				hasDeny = true
316			}
317		}
318		sort.Strings(matched)
319		return matched, hasAllow, hasDeny
320	}
321	
322	// scopeCovers reports whether resourceScope is covered by policyScope. When
323	// recursive is false the scopes must be equal. When recursive is true the
324	// policy also covers every scope below policyScope: path segments are matched
325	// between slashes, so "org/a" covers "org/a" and "org/a/b" but not "org/ab".
326	func scopeCovers(policyScope, resourceScope string, recursive bool) bool {
327		if policyScope == resourceScope {
328			return true
329		}
330		return recursive && strings.HasPrefix(resourceScope, policyScope+"/")
331	}
332	
333	// validScopePath reports whether p is a valid scope path. A path must be
